// while satisfying *.cisco.com base URL validation.
package apitest

import (
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"

	"github.com/cisco-ai-defense/ai-defense-cli/api"
	"github.com/cisco-ai-defense/ai-defense-cli/internal/cmdutil"
